import UIKit

class ContentTableViewController: UIViewController, UITableViewDelegate, UITableViewDataSource {
    
    @IBOutlet weak var tableView: UITableView! // Connect this in storyboard
    
    let details = ["""
                   <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Immediate Steps</title><style>body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 16px; color: #333; line-height: 1.6; margin: 20px; padding: 20px; background-color: #f9f9f9; } h1 { font-size: 22px; font-weight: bold; color: #1a73e8; text-align: center; } h2 { font-size: 18px; margin-top: 20px; color: #333; } ul { padding-left: 20px; } li { margin-bottom: 10px; }</style></head><body><h1>Immediate Steps</h1><h2>Stay Calm and Assess:</h2><ul><li><strong>Confirm Your Car Is Missing:</strong> Before assuming theft, verify that your car hasn’t been towed or borrowed (e.g., by a family member). Check for signs like broken glass or unfamiliar vehicles nearby that might indicate theft.</li><li><strong>Check for Towing:</strong> Contact local towing companies, your city’s parking enforcement, or municipal impound lots to rule out towing due to parking violations or street cleaning. Have your license plate number ready for quick verification.</li><li><strong>Ensure Personal Safety:</strong> If you’re in an isolated or unsafe area, move to a well-lit, public location (like a store or gas station) before proceeding. Avoid confronting suspicious individuals—let the police handle it. If you feel uneasy, call a friend or family member to stay with you.</li></ul><h2>Contact Authorities:</h2><ul><li><strong>Call the Non-Emergency Line:</strong> Unless you witness the theft in progress (then call 911), use the police non-emergency number to report the theft. Provide detailed information: make, model, year, color, license plate number, VIN (Vehicle Identification Number), and any distinguishing features (e.g., bumper stickers, dents).</li><li><strong>Prepare in Advance:</strong> Store your car’s details in your phone or wallet for easy access during this stressful moment.</li><li><strong>Get Documentation:</strong> Request a copy of the police report or at least the report number. This is essential for insurance claims and tracking the investigation.</li></ul><h2>Notify Your Insurance:</h2><ul><li><strong>Report Promptly:</strong> Call your insurance provider as soon as possible with the police report number. Ask about your coverage for theft, including timelines for filing a claim.</li><li><strong>Inquire About Details:</strong> Ask if rental car costs are covered while your claim is processed, what your deductible is for theft claims, and what documentation they’ll need (e.g., police report, proof of ownership).</li><li><strong>Understand the Process:</strong> Clarify next steps, such as whether they’ll reimburse you for a replacement or cover repairs if the car is recovered.</li></ul><h2>Alert Your Lender/Leasing Company:</h2><ul><li><strong>Prevent Liability Issues:</strong> If your car is financed or leased, inform your lender or leasing company immediately. This ensures you’re not held responsible for missed payments or misuse of the vehicle.</li><li><strong>Keep Contact Info Handy:</strong> Store their phone number in your phone or records for quick access.</li></ul><h2>Check for Tracking or GPS:</h2><ul><li><strong>Use Built-In Systems:</strong> If your car has GPS (e.g., OnStar, LoJack), activate it to track the vehicle’s location and inform the police. Provide the tracking service with the police report number for coordination.</li><li><strong>Future Investment:</strong> Note that some insurance companies offer discounts for cars with tracking systems—consider this for prevention.</li></ul><h2>Spread the Word:</h2><ul><li><strong>Leverage Community Help:</strong> Post about the theft on social media, Nextdoor, or local forums. Include your car’s make, model, color, license plate number, and a photo if available to aid recognition.</li><li><strong>Use Theft Apps:</strong> Report the theft to services like Stolen911 or local car recovery networks, if available in your area.</li></ul></body></html>

                   """, """
                        <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Prevention: How to Prevent Car Theft</title><style>body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 16px; color: #333; line-height: 1.6; margin: 20px; padding: 20px; background-color: #f9f9f9; } h1 { font-size: 22px; font-weight: bold; color: #1a73e8; text-align: center; } h2 { font-size: 18px; margin-top: 20px; color: #333; } ul { padding-left: 20px; } li { margin-bottom: 10px; }</style></head><body><h1>Prevention: How to Prevent Car Theft</h1><h2>General Tips:</h2><ul><li><strong>Lock Up Every Time:</strong> Always lock your doors and roll up windows, even for quick stops. Many thefts are opportunistic.</li><li><strong>Hide Keys:</strong> Never leave spare keys in or near the car (e.g., under the mat or in a wheel well). Use a secure key storage solution at home.</li><li><strong>Avoid Temptation:</strong> Don’t leave valuables (or even charging cables) in plain sight—store them in the glove compartment or trunk.</li><li><strong>Install Deterrents:</strong> Equip your car with an alarm or GPS tracking system. Audible alarms scare off thieves, while GPS aids recovery.</li><li><strong>Smart Parking:</strong> Park in well-lit, busy areas near entrances or pedestrian traffic. If in a less secure spot, choose a location near security cameras or with high visibility.</li><li><strong>Anti-Theft Devices:</strong> Use a steering wheel lock, pedal lock, or gear shift lock as a visible deterrent.</li></ul><h2>Advanced Protection:</h2><ul><li><strong>Kill Switch:</strong> Install a hidden kill switch or ignition disabler to prevent the car from starting. Consult a mechanic for professional installation.</li><li><strong>Smartphone Tracking:</strong> Use apps or devices that notify you of tampering and allow real-time tracking.</li><li><strong>Tinted Windows:</strong> Apply tinted windows to reduce visibility inside, but check local laws for legal tint limits.</li></ul><h2>Keep Your Car’s Appearance Low-Key:</h2><ul><li><strong>Stay Subtle:</strong> Avoid flashy rims, decals, or accessories that draw attention. A low-profile car is less likely to be targeted.</li><li><strong>Secure Valuables:</strong> Remove or hide anything valuable, including items that hint at hidden gadgets (e.g., phone mounts, bags).</li></ul><h2>Home and Neighborhood Safety:</h2><ul><li><strong>Light It Up:</strong> Install motion-sensor lights in your driveway or garage to deter nighttime theft.</li><li><strong>Secure Access:</strong> Lock garage doors, gates, and fences. Use sturdy padlocks if needed.</li><li><strong>Community Effort:</strong> Join or start a neighborhood watch group and use online platforms (e.g., Ring Neighborhoods) to share alerts about suspicious activity.</li><li><strong>Surveillance:</strong> Install a dash cam or home security cameras overlooking your parking area for deterrence and evidence.</li></ul></body></html>

                        ""","""
                        <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Aftermath: Steps to Take After the Car Is Stolen</title><style>body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 16px; color: #333; line-height: 1.6; margin: 20px; padding: 20px; background-color: #f9f9f9; } h1 { font-size: 22px; font-weight: bold; color: #1a73e8; text-align: center; } h2 { font-size: 18px; margin-top: 20px; color: #333; } ul { padding-left: 20px; } li { margin-bottom: 10px; }</style></head><body><h1>Aftermath: Steps to Take After the Car Is Stolen</h1><h2>Car Recovery:</h2><ul><li><strong>Follow Up with Police:</strong> Regularly check with the police for updates on their investigation. Provide any new information (e.g., GPS data).</li><li><strong>Check Impound Lots:</strong> Contact local impound lots or towing services—stolen cars are often abandoned and towed.</li></ul><h2>Work with Insurance:</h2><ul><li><strong>Submit Documentation:</strong> Provide the police report, proof of ownership (title/registration), and any photos of the car. Keep a file with all related documents.</li><li><strong>Understand Coverage:</strong> Confirm what’s covered—replacement value, repairs, or rental costs—and the timeline for payouts.</li><li><strong>Claims Process:</strong> If recovered, the insurer may pay for repairs; if not, they might declare it a total loss and offer compensation.</li></ul><h2>Vehicle Damage Assessment:</h2><ul><li><strong>Inspect Thoroughly:</strong> If your car is recovered, check for visible damage (e.g., scratches, missing parts) and take photos/notes for insurance.</li><li><strong>Mechanic Review:</strong> Have a professional mechanic inspect for hidden damage or tampering (e.g., altered wiring, engine issues).</li></ul><h2>Avoid Fraud:</h2><ul><li><strong>Watch for Scams:</strong> Be wary of people contacting you claiming to have your car—verify with police first.</li><li><strong>Monitor Online:</strong> Search marketplaces like Craigslist, eBay, or Facebook Marketplace for your car or its parts. Set up keyword alerts using your car’s make/model.</li></ul><h2>Legal Issues:</h2><ul><li><strong>Crime Involvement:</strong> If your car was used in a crime, cooperate fully with police. Keep records of all interactions.</li><li><strong>Legal Support:</strong> Consult a lawyer if you face liability or need to navigate complex legal fallout.</li></ul><h2>Emotional Impact:</h2><ul><li><strong>Address Stress:</strong> Car theft can feel like a personal violation, causing anxiety or anger. Talk to a counselor, friend, or support group to process it.</li><li><strong>Take Care:</strong> Give yourself time to recover emotionally while handling practical steps.</li></ul></body></html>

                        """, """
                            <!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Long-Term Considerations</title><style>body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; font-size: 16px; color: #333; line-height: 1.6; margin: 20px; padding: 20px; background-color: #f9f9f9; } h1 { font-size: 22px; font-weight: bold; color: #1a73e8; text-align: center; } h2 { font-size: 18px; margin-top: 20px; color: #333; } ul { padding-left: 20px; } li { margin-bottom: 10px; }</style></head><body><h1>Long-Term Considerations</h1><h2>Reevaluate Insurance:</h2><ul><li><strong>Upgrade Coverage:</strong> If your policy didn’t include theft protection, add it. Ask about comprehensive coverage options.</li><li><strong>New Car Features:</strong> If replacing your car, prioritize models with advanced security (e.g., immobilizers, GPS).</li></ul><h2>Stay Vigilant:</h2><ul><li><strong>Stay Alert:</strong> Watch for suspicious activity near your vehicle, especially in high-theft areas.</li><li><strong>Online Monitoring:</strong> Regularly check online listings for stolen cars or parts matching your vehicle’s description.</li></ul><h2>Record Keeping:</h2><ul><li><strong>Organize Documents:</strong> Keep a file with the police report, insurance correspondence, and repair records for reference.</li><li><strong>Digital Backup:</strong> Scan and store copies digitally for easy access.</li></ul></body></html>
                    """ ]
    
    let rowNames = ["Immediate Steps","Steps to Take After the Car Is Stolen","How to Prevent Car Theft","Long-Term Considerations"]
    override func viewDidLoad() {
        super.viewDidLoad()
        
        tableView.delegate = self
        tableView.dataSource = self
        tableView.register(UITableViewCell.self, forCellReuseIdentifier: "cell")
    }
    
    // MARK: - Table view data source
    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return 4
    }
    
    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "cell", for: indexPath)
        cell.textLabel?.text = rowNames[indexPath.row]
        cell.textLabel?.font = UIFont.systemFont(ofSize: 16, weight: .medium)
        return cell
    }
    
    func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        performSegue(withIdentifier: "ScrollViewController", sender: details[indexPath.row])
    }
    
    func tableView(_ tableView: UITableView, heightForRowAt indexPath: IndexPath) -> CGFloat {
        return 70
    }
    
    override func prepare(for segue: UIStoryboardSegue, sender: Any?) {
        if segue.identifier == "ScrollViewController",
           let vc = segue.destination as? ScrollViewController,
           let detailText = sender as? String {
            vc.textToDisplay = detailText
        }
    }
}
